from __future__ import annotations

from dataclasses import dataclass
from typing import Mapping

from .enums import (
    AIQueryStatus,
    DocumentState,
    ExportJobStatus,
    ExtractedFieldStatus,
    NotificationStatus,
    TaskStatus,
)


@dataclass(frozen=True)
class LifecycleRule:
    all_states: frozenset[str]
    initial_states: frozenset[str]
    allowed: Mapping[str, frozenset[str]]
    forbid_same_state_updates: frozenset[str] = frozenset()


def _enum_values(enum_cls: type) -> frozenset[str]:
    return frozenset(item.value for item in enum_cls)


_RULES: dict[str, LifecycleRule] = {
    "document": LifecycleRule(
        all_states=_enum_values(DocumentState),
        initial_states=frozenset({DocumentState.UPLOADED.value}),
        allowed={
            DocumentState.UPLOADED.value: frozenset({DocumentState.PROCESSING.value}),
            DocumentState.PROCESSING.value: frozenset(
                {
                    DocumentState.VALIDATION_READY.value,
                    DocumentState.EXCEPTION.value,
                }
            ),
            DocumentState.VALIDATION_READY.value: frozenset(
                {DocumentState.VALIDATED.value}
            ),
        },
        forbid_same_state_updates=frozenset({DocumentState.EXPORTED.value}),
    ),
    "extracted_field": LifecycleRule(
        all_states=_enum_values(ExtractedFieldStatus),
        initial_states=frozenset({ExtractedFieldStatus.PROPOSED.value}),
        allowed={
            ExtractedFieldStatus.PROPOSED.value: frozenset(
                {
                    ExtractedFieldStatus.CORRECTED.value,
                    ExtractedFieldStatus.ACCEPTED.value,
                    ExtractedFieldStatus.REJECTED.value,
                }
            ),
            ExtractedFieldStatus.CORRECTED.value: frozenset(
                {ExtractedFieldStatus.ACCEPTED.value}
            ),
        },
    ),
    "task": LifecycleRule(
        all_states=_enum_values(TaskStatus),
        initial_states=frozenset(
            {
                TaskStatus.OPEN.value,
                TaskStatus.EXCEPTION.value,
            }
        ),
        allowed={
            TaskStatus.OPEN.value: frozenset(
                {
                    TaskStatus.IN_PROGRESS.value,
                    TaskStatus.COMPLETED.value,
                    TaskStatus.EXCEPTION.value,
                }
            ),
            TaskStatus.IN_PROGRESS.value: frozenset(
                {
                    TaskStatus.COMPLETED.value,
                    TaskStatus.EXCEPTION.value,
                }
            ),
        },
    ),
    "notification": LifecycleRule(
        all_states=_enum_values(NotificationStatus),
        initial_states=frozenset({NotificationStatus.PENDING.value}),
        allowed={
            NotificationStatus.PENDING.value: frozenset(
                {
                    NotificationStatus.SENT.value,
                    NotificationStatus.FAILED.value,
                }
            ),
            NotificationStatus.SENT.value: frozenset({NotificationStatus.READ.value}),
        },
    ),
    "export_job": LifecycleRule(
        all_states=_enum_values(ExportJobStatus),
        initial_states=frozenset({ExportJobStatus.REQUESTED.value}),
        allowed={
            ExportJobStatus.REQUESTED.value: frozenset(
                {ExportJobStatus.RUNNING.value}
            ),
            ExportJobStatus.RUNNING.value: frozenset(
                {
                    ExportJobStatus.COMPLETED.value,
                    ExportJobStatus.FAILED.value,
                }
            ),
        },
    ),
    "ai_query": LifecycleRule(
        all_states=_enum_values(AIQueryStatus),
        initial_states=frozenset({AIQueryStatus.REQUESTED.value}),
        allowed={
            AIQueryStatus.REQUESTED.value: frozenset(
                {
                    AIQueryStatus.COMPLETED.value,
                    AIQueryStatus.DENIED.value,
                    AIQueryStatus.FAILED.value,
                }
            ),
        },
    ),
}


def _get_rule(entity: str) -> LifecycleRule:
    try:
        return _RULES[entity]
    except KeyError as exc:
        raise ValueError(
            f"unknown lifecycle entity: {entity}. allowed: {sorted(_RULES)}"
        ) from exc


def is_allowed_initial_state(entity: str, state: str) -> bool:
    rule = _get_rule(entity)
    return state in rule.initial_states


def assert_allowed_initial_state(entity: str, state: str) -> None:
    rule = _get_rule(entity)
    if state not in rule.initial_states:
        raise ValueError(
            f"invalid initial state for {entity}: {state}. "
            f"allowed initial states: {sorted(rule.initial_states)}. "
            f"known states: {sorted(rule.all_states)}"
        )


def is_allowed_transition(entity: str, previous_state: str, next_state: str) -> bool:
    rule = _get_rule(entity)

    if previous_state not in rule.all_states or next_state not in rule.all_states:
        return False

    if previous_state == next_state:
        return previous_state not in rule.forbid_same_state_updates

    return next_state in rule.allowed.get(previous_state, frozenset())


def assert_allowed_transition(entity: str, previous_state: str, next_state: str) -> None:
    rule = _get_rule(entity)

    if previous_state not in rule.all_states:
        raise ValueError(
            f"unknown previous state for {entity}: {previous_state}. "
            f"known states: {sorted(rule.all_states)}"
        )

    if next_state not in rule.all_states:
        raise ValueError(
            f"unknown next state for {entity}: {next_state}. "
            f"known states: {sorted(rule.all_states)}"
        )

    if not is_allowed_transition(entity, previous_state, next_state):
        raise ValueError(
            f"invalid transition for {entity}: {previous_state} -> {next_state}"
        )
