def _upgrade(alembic_config) -> None:
    command.upgrade(alembic_config, "head")


def _downgrade(alembic_config) -> None:
    command.downgrade(alembic_config, "base")


def _engine(database_url: str):
    return create_engine(database_url)


def _seed_users(connection) -> None:
    connection.execute(
        text(
            """
            INSERT INTO users (
                id, deployment_profile, username, display_name, role, idp_group_refs, active
            ) VALUES
                ('user-uploader', 'local', 'operator.upload', 'Operatore Upload', 'operator', CAST(:groups AS jsonb), true),
                ('user-validator', 'local', 'operator.validate', 'Operatore Validazione', 'validator', CAST(:groups AS jsonb), true),
                ('user-aws', 'aws', 'operator.upload', 'Operatore AWS', 'operator', CAST(:groups AS jsonb), true)
            """
        ),
        {"groups": json.dumps(["operators"])},
    )


def _enum_labels(connection, enum_name: str) -> set[str]:
    return {
        row[0]
        for row in connection.execute(
            text(
                """
                SELECT e.enumlabel
                FROM pg_enum e
                JOIN pg_type t ON t.oid = e.enumtypid
                WHERE t.typname = :enum_name
                """
            ),
            {"enum_name": enum_name},
        )
    }


